--
-- Table structure for table `activity_logs`
--

CREATE TABLE `activity_logs` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `user_type` enum('admin','resident','staff','official') NOT NULL DEFAULT 'resident',
  `username` varchar(100) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `action` enum('login','logout','session_expired','approve_registration','reject_registration','undo_registration','approve_profile_update','edit_resident','delete_resident','restore_resident') NOT NULL DEFAULT 'login',
  `login_at` datetime NOT NULL DEFAULT current_timestamp(),
  `logout_at` datetime DEFAULT NULL,
  `duration_sec` int(11) DEFAULT NULL COMMENT 'logout_at - login_at in seconds',
  `ip_address` varchar(45) NOT NULL DEFAULT '' COMMENT 'IPv4 or IPv6',
  `country` varchar(100) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `region` varchar(100) DEFAULT NULL,
  `latitude` decimal(10,6) DEFAULT NULL,
  `longitude` decimal(10,6) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `device_type` enum('Desktop','Mobile','Tablet','Unknown') NOT NULL DEFAULT 'Unknown',
  `os` varchar(100) DEFAULT NULL,
  `browser` varchar(100) DEFAULT NULL,
  `status` enum('online','offline','expired') NOT NULL DEFAULT 'online',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `details` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

